// Screen 04 of 29. Generated by Google Stitch, source folder 4-map_results.
// Rebuilt 3 August 2026, rebuilt to the Stitch layout 29 August 2026.
//
// WHAT WAS WRONG WITH THE GENERATED VERSION
// The map was `Container(color: Colors.grey.shade200)` with a grey icon, and
// the four price pins were `Positioned` widgets at fixed pixel offsets. Those
// pins would sit still while the map panned underneath them, so a listing
// would appear to be somewhere it is not. That is worse than no map.
//
// Real markers move with the map because they belong to it.
//
// ── ⚠ THE SCREEN WAS EMPTY ON EVERY OPEN. Fixed 29 August 2026. ─────────────
//
// This widget has accepted a `listings` list since it was written. The route
// built it as `const MapResultsScreen()`, so the list was ALWAYS empty and the
// screen always rendered its own "Nothing to show on the map" state. Nobody
// read that as a fault, because an empty map with a tidy empty state looks
// exactly like a search that found nothing.
//
// Same shape of fault as screens 07 and 08 had: a live route with nothing
// behind it. See stay_routes.dart.
//
// ── ⚠ THE PRICE BUBBLES ARE THE SCREEN ──────────────────────────────────────
//
// This file used to carry a TODO saying a custom price bubble was "worth
// doing, not worth blocking on", and drew Google's default teardrop pins with
// two different hues instead.
//
// That TODO had the priority backwards. A map of anonymous pins tells a guest
// where properties are, which they can guess. A map of PRICES tells them where
// the cheap end of town is, which is the entire reason a person switches from
// the list to the map. Stitch draws the price in every pin for that reason.
//
// The bubbles are painted here, cached by price and selection state, so a
// screen of thirty listings paints a handful of bitmaps rather than thirty.
//
// MEMORY. This app has previously been killed by iOS Jetsam, and a map is one
// of the three heaviest things a Flutter app can do. Three rules now:
//   * ONE GoogleMap alive at a time across the whole Short Stay feature
//   * the controller is disposed, following widgets/live_tracking_map.dart
//   * every ui.Image is disposed the moment its bytes are taken
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:google_fonts/google_fonts.dart';
import 'package:google_maps_flutter/google_maps_flutter.dart';
// ⚠ hide TextDirection. package:intl EXPORTS ITS OWN TextDirection, a bidi
// helper class with static LTR/RTL constants, and it is a completely different
// type from the dart:ui enum that TextPainter takes. Imported plainly it wins
// the name, and the only symptom is "the getter 'ltr' isn't defined for the
// type 'TextDirection'" pointing at a line that has nothing to do with intl.
//
// Any file in this feature that formats a date AND paints text needs this.
import 'package:intl/intl.dart' hide TextDirection;

import '../models/stay_listing.dart';
import '../services/stay_availability_service.dart';
import '../stay_routes.dart';
import '../theme/stay_colors.dart';
import '../theme/stay_type.dart';
import '../widgets/stay_bottom_nav.dart';

class MapResultsScreen extends StatefulWidget {
  const MapResultsScreen({
    super.key,
    this.listings = const <StayListing>[],
    this.criteria,
    this.onOpenListing,
    this.onShowList,
  });

  /// The same result set the list view is showing. Passed in rather than
  /// fetched here, so the two views cannot disagree about what was found.
  final List<StayListing> listings;

  /// Only for the header. Stitch puts "Richmond / 2 guests, 12 to 15 May" at
  /// the top of this screen, and without it a guest who has panned the map has
  /// no way of telling which search they are looking at.
  final StaySearchCriteria? criteria;

  final void Function(String listingId)? onOpenListing;
  final VoidCallback? onShowList;

  @override
  State<MapResultsScreen> createState() => _MapResultsScreenState();
}

class _MapResultsScreenState extends State<MapResultsScreen> {
  // Charing Cross. The conventional point from which distances to London are
  // measured, and a sane fallback when no listing has coordinates yet.
  static const LatLng _fallbackCentre = LatLng(51.50735, -0.12776);

  GoogleMapController? _map;
  final PageController _cards = PageController(viewportFraction: 0.86);
  int _selected = 0;

  Set<Marker> _markers = <Marker>{};

  /// Painted bubbles, keyed by "£112|selected|2.0". A result set of thirty
  /// listings in one town usually contains six or seven distinct prices, so
  /// this turns thirty canvas renders per selection change into about seven,
  /// once, for the life of the screen.
  final Map<String, BitmapDescriptor> _bubbles = <String, BitmapDescriptor>{};

  @override
  void initState() {
    super.initState();
    // ⚠ POST FRAME, not here. Two reasons: the device pixel ratio comes from
    // MediaQuery, which is not available during initState; and the Inter font
    // has to be resident before it can be painted into a bitmap, or the
    // bubbles bake in the fallback typeface permanently.
    WidgetsBinding.instance.addPostFrameCallback((_) => _rebuildMarkers());
  }

  @override
  void didUpdateWidget(covariant MapResultsScreen old) {
    super.didUpdateWidget(old);
    if (old.listings != widget.listings) {
      _selected = 0;
      _rebuildMarkers();
    }
  }

  @override
  void dispose() {
    // Both, always. A leaked map controller holds native resources.
    _map?.dispose();
    _cards.dispose();
    super.dispose();
  }

  List<StayListing> get _plottable => widget.listings
      .where((StayListing l) => l.lat != null && l.lng != null)
      .toList();

  LatLng get _initialCentre {
    final List<StayListing> p = _plottable;
    if (p.isEmpty) return _fallbackCentre;
    return LatLng(p.first.lat!, p.first.lng!);
  }

  /// ── ⚠ FRAME EVERY RESULT, DO NOT GUESS A ZOOM. 29 August 2026. ────────────
  ///
  ///  This screen opened at a FIXED zoom 13 centred on whichever listing
  ///  happened to be first in the list. Results spread across a city sat
  ///  outside the viewport with nothing to suggest they existed — a guest
  ///  looking at three pins on a map of eleven results has no way to know, and
  ///  the carousel underneath would scroll to a card whose pin was off screen.
  ///
  ///  Zoom 13 is also wrong in both directions: too far out for two properties
  ///  on the same street, too far in for a search across Greater London.
  ///
  ///  ⚠ A SINGLE PIN CANNOT BE FRAMED. LatLngBounds needs two distinct corners,
  ///  and a bounds where southwest equals northeast either throws or zooms to
  ///  the maximum, putting one property at street level with no context. One
  ///  result therefore gets an explicit zoom instead.
  Future<void> _frameAllPins() async {
    final GoogleMapController? map = _map;
    final List<StayListing> p = _plottable;
    if (map == null || p.isEmpty) return;

    if (p.length == 1) {
      await map.animateCamera(
        CameraUpdate.newLatLngZoom(LatLng(p.first.lat!, p.first.lng!), 14),
      );
      return;
    }

    double minLat = p.first.lat!;
    double maxLat = p.first.lat!;
    double minLng = p.first.lng!;
    double maxLng = p.first.lng!;
    for (final StayListing l in p) {
      if (l.lat! < minLat) minLat = l.lat!;
      if (l.lat! > maxLat) maxLat = l.lat!;
      if (l.lng! < minLng) minLng = l.lng!;
      if (l.lng! > maxLng) maxLng = l.lng!;
    }

    // ⚠ A FLOOR ON THE SPAN. Two properties in the same building differ by
    // metres, and a bounds that small zooms to the maximum for the same reason
    // a single pin does.
    const double minSpan = 0.01; // roughly 1km
    if (maxLat - minLat < minSpan) {
      final double mid = (maxLat + minLat) / 2;
      minLat = mid - minSpan / 2;
      maxLat = mid + minSpan / 2;
    }
    if (maxLng - minLng < minSpan) {
      final double mid = (maxLng + minLng) / 2;
      minLng = mid - minSpan / 2;
      maxLng = mid + minSpan / 2;
    }

    try {
      await map.animateCamera(
        CameraUpdate.newLatLngBounds(
          LatLngBounds(
            southwest: LatLng(minLat, minLng),
            northeast: LatLng(maxLat, maxLng),
          ),
          // Padding in logical pixels. Generous because the List pill sits over
          // the top of the map and the card carousel over the bottom, so a pin
          // framed tightly would be underneath one of them.
          64,
        ),
      );
    } catch (_) {
      // newLatLngBounds throws if the map has not laid out yet. The initial
      // camera position is already sensible, so failing quietly is correct.
    }
  }

  // ── Markers ────────────────────────────────────────────────────────────────

  Future<void> _rebuildMarkers() async {
    if (!mounted) return;
    final List<StayListing> plottable = _plottable;
    if (plottable.isEmpty) {
      if (_markers.isNotEmpty) setState(() => _markers = <Marker>{});
      return;
    }

    // The bubbles are painted with Inter. If it has not finished loading, the
    // canvas silently falls back to Roboto and the pins stay wrong until the
    // screen is rebuilt, so wait for it rather than race it.
    await GoogleFonts.pendingFonts(<TextStyle>[GoogleFonts.inter()]);
    if (!mounted) return;

    final double dpr = MediaQuery.devicePixelRatioOf(context);
    final Set<Marker> next = <Marker>{};

    for (int i = 0; i < plottable.length; i++) {
      final StayListing l = plottable[i];
      final bool on = i == _selected;
      final BitmapDescriptor icon =
          await _priceBubble(l.nightlyRate.compact, on, dpr);
      if (!mounted) return;
      next.add(
        Marker(
          markerId: MarkerId(l.id),
          position: LatLng(l.lat!, l.lng!),
          icon: icon,
          // The selected bubble sits above its neighbours, so a cheap pin does
          // not disappear behind an expensive one the moment it is chosen.
          zIndexInt: on ? 2 : 1,
          // ⚠ The anchor is the TIP OF THE TAIL, not the centre of the bubble.
          // At the default (0.5, 1.0) the tail lands exactly on the building,
          // which is the whole point of drawing a tail.
          anchor: const Offset(0.5, 1),
          onTap: () => _selectListing(i),
        ),
      );
    }

    if (!mounted) return;
    setState(() => _markers = next);
  }

  /// Paints "£112" into a rounded bubble with a pointer, as a map bitmap.
  ///
  /// Selected is the filled blue bubble with white text; everything else is
  /// white with blue text and a hairline outline, which is what Stitch draws.
  Future<BitmapDescriptor> _priceBubble(
      String label, bool selected, double dpr) async {
    final String key = '$label|$selected|$dpr';
    final BitmapDescriptor? cached = _bubbles[key];
    if (cached != null) return cached;

    const double padH = 12;
    const double padV = 6;
    const double tailH = 7;
    const double tailW = 12;
    const double radius = 16;

    final TextPainter tp = TextPainter(
      text: TextSpan(
        text: label,
        style: StayType.price.on(
          selected ? GoOutsColors.cardSurface : GoOutsColors.primaryBlue,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();

    final double w = tp.width + padH * 2;
    final double h = tp.height + padV * 2;
    final double totalH = h + tailH;

    final ui.PictureRecorder recorder = ui.PictureRecorder();
    final Canvas canvas = Canvas(recorder);
    canvas.scale(dpr);

    // ⚠ ui.PathOperation, not a bare PathOperation. flutter/painting re-exports
    // Path from dart:ui but NOT PathOperation, so the unprefixed name does not
    // resolve here even though Path directly above it does.
    final Path shape = Path.combine(
      ui.PathOperation.union,
      Path()
        ..addRRect(RRect.fromRectAndRadius(
          Rect.fromLTWH(0, 0, w, h),
          const Radius.circular(radius),
        )),
      // Overlaps the body by half a pixel so the union has no seam along the
      // join, which shows as a white hairline on a dark bubble.
      Path()
        ..moveTo(w / 2 - tailW / 2, h - 0.5)
        ..lineTo(w / 2, totalH)
        ..lineTo(w / 2 + tailW / 2, h - 0.5)
        ..close(),
    );

    canvas.drawShadow(shape, Colors.black.withValues(alpha: 0.3), 2, false);
    canvas.drawPath(
      shape,
      Paint()
        ..isAntiAlias = true
        ..color =
            selected ? GoOutsColors.primaryBlue : GoOutsColors.cardSurface,
    );
    if (!selected) {
      canvas.drawPath(
        shape,
        Paint()
          ..isAntiAlias = true
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1
          ..color = GoOutsColors.outlineVariant,
      );
    }
    tp.paint(canvas, const Offset(padH, padV));

    // ⚠ THE PICTURE IS HELD, NOT CHAINED. Written as
    // `recorder.endRecording().toImage(...)` the Picture has no name and can
    // never be disposed, and a ui.Picture holds native memory the Dart garbage
    // collector does not account for. Same reason as the Image below.
    final ui.Picture picture = recorder.endRecording();
    final ui.Image image =
        await picture.toImage((w * dpr).ceil(), (totalH * dpr).ceil());
    // Inferred rather than annotated ByteData? on purpose. ByteData lives in
    // dart:typed_data, and importing it here would be reported as an unused
    // import because flutter/foundation already re-exports the name.
    final data = await image.toByteData(format: ui.ImageByteFormat.png);

    // ⚠ ALL THREE DISPOSED, AND ONLY AFTER BOTH AWAITS. tp.dispose() releases
    // the ui.Paragraph that was drawn into the picture, so disposing it any
    // earlier would tear down the text before the raster thread had drawn it.
    image.dispose();
    picture.dispose();
    tp.dispose();

    if (data == null) return BitmapDescriptor.defaultMarker;

    final BitmapDescriptor made = BitmapDescriptor.bytes(
      data.buffer.asUint8List(),
      imagePixelRatio: dpr,
    );
    _bubbles[key] = made;
    return made;
  }

  Future<void> _selectListing(int index) async {
    final List<StayListing> plottable = _plottable;
    if (index < 0 || index >= plottable.length) return;
    setState(() => _selected = index);
    // Repaint so the newly chosen bubble fills and the old one empties.
    // Deliberately not awaited before the camera moves: the pin can catch up a
    // frame later, the camera should not wait for a bitmap.
    _rebuildMarkers();

    if (_cards.hasClients) {
      await _cards.animateToPage(
        index,
        duration: const Duration(milliseconds: 250),
        curve: Curves.easeOut,
      );
    }
    // The animateToPage above is awaited, so the widget may have been
    // disposed by the time we get here. Touching a disposed map controller
    // throws, and it is the classic crash-on-back-button.
    if (!mounted) return;
    final StayListing l = plottable[index];
    await _map?.animateCamera(
      CameraUpdate.newLatLng(LatLng(l.lat!, l.lng!)),
    );
  }

  void _openListing(String listingId) {
    // ⚠ FALLS BACK TO THE ROUTE. The callback is null whenever this screen is
    // reached through stay_routes, which is every real journey — a named route
    // cannot carry a closure. Without this branch the cards were simply not
    // tappable there, which is the only way into a property from the map.
    if (widget.onOpenListing != null) {
      widget.onOpenListing!(listingId);
      return;
    }
    Navigator.of(context).pushNamed(
      StayRoutes.listing,
      arguments: <String, dynamic>{'listingId': listingId},
    );
  }

  // ── Header text ────────────────────────────────────────────────────────────

  String get _title {
    final String? town = widget.criteria?.town?.trim();
    if (town != null && town.isNotEmpty) return town;
    for (final StayListing l in widget.listings) {
      if (l.address.town.isNotEmpty) return l.address.town;
    }
    return 'On the map';
  }

  String get _subtitle {
    final StaySearchCriteria? c = widget.criteria;
    final List<String> parts = <String>[];
    final int guests = c?.guests ?? 1;
    parts.add('$guests ${guests == 1 ? 'guest' : 'guests'}');
    if (c != null && c.hasDates) parts.add(_dateRange(c.checkIn!, c.checkOut!));
    return parts.join('  •  ');
  }

  /// "12 to 15 May" inside one month, "28 Aug to 2 Sep" across two. Written
  /// out rather than dashed, to match how the rest of the app reads.
  String _dateRange(DateTime from, DateTime to) {
    final DateFormat day = DateFormat('d');
    final DateFormat dayMonth = DateFormat('d MMM');
    return from.year == to.year && from.month == to.month
        ? '${day.format(from)} to ${dayMonth.format(to)}'
        : '${dayMonth.format(from)} to ${dayMonth.format(to)}';
  }

  // ── Build ──────────────────────────────────────────────────────────────────

  @override
  Widget build(BuildContext context) {
    final List<StayListing> plottable = _plottable;

    return Scaffold(
      backgroundColor: GoOutsColors.pageBackground,
      appBar: AppBar(
        backgroundColor: GoOutsColors.cardSurface,
        surfaceTintColor: Colors.transparent,
        elevation: 0,
        // Two lines of text: screen-title at 28 plus body at 20. 64 leaves the
        // pair breathing room without turning the header into a banner.
        toolbarHeight: 64,
        shape: const Border(
          bottom: BorderSide(color: GoOutsColors.outlineVariant, width: 0.5),
        ),
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: GoOutsColors.primaryBlue),
          onPressed: () => Navigator.of(context).maybePop(),
        ),
        titleSpacing: 0,
        title: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            Text(
              _title,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: StayType.screenTitle.on(GoOutsColors.deepNavy),
            ),
            Text(
              _subtitle,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: StayType.body.on(GoOutsColors.bodyText),
            ),
          ],
        ),
        actions: <Widget>[
          // ⚠ STARTS A NEW SEARCH, and that is the only thing it does. Back and
          // the List pill both return to these same results, so a third control
          // that also went back would be decoration. A magnifier beside a
          // search summary means "search for something else" everywhere else on
          // a phone, so that is what it does here.
          IconButton(
            icon: const Icon(Icons.search, color: GoOutsColors.deepNavy),
            tooltip: 'New search',
            onPressed: () => Navigator.of(context)
                .pushNamedAndRemoveUntil(StayRoutes.home, (Route<dynamic> r) => r.isFirst),
          ),
        ],
      ),
      bottomNavigationBar: const StayBottomNav(current: StayTab.search),
      body: LayoutBuilder(
        builder: (context, constraints) {
          final bool desktop = kIsWeb && constraints.maxWidth >= 900;
          final Widget content = Stack(
        children: <Widget>[
          if (plottable.isEmpty)
            _emptyMap()
          else
            GoogleMap(
              initialCameraPosition:
                  CameraPosition(target: _initialCentre, zoom: 13),
              markers: _markers,
              myLocationEnabled: false,
              myLocationButtonEnabled: false,
              zoomControlsEnabled: false,
              mapToolbarEnabled: false,
              compassEnabled: false,
              // Room for the pill at the top and the card at the bottom, so
              // Google's own logo and the selected pin are never underneath
              // something of ours. Required by the Maps terms as well.
              padding: const EdgeInsets.only(top: 60, bottom: 150),
              onMapCreated: (GoogleMapController c) {
                _map = c;
                // ⚠ NOT IMMEDIATELY. onMapCreated fires before the platform
                // view has its final size, and newLatLngBounds throws when it
                // is called against a map that has not laid out. One frame is
                // enough, and the initial camera position covers the gap.
                WidgetsBinding.instance
                    .addPostFrameCallback((_) => _frameAllPins());
              },
            ),

          // ⚠ AT THE TOP, not floating at the bottom. Stitch puts the switch
          // back to the list directly under the header, where the eye already
          // is after reading which search this is. Ours sat at the bottom and
          // collided with the card carousel.
          _listToggle(),

          if (plottable.isNotEmpty) _carousel(plottable),
        ],
      );
          if (!desktop) return content;
          return Center(
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 900),
              child: content,
            ),
          );
        },
      ),
    );
  }

  Widget _emptyMap() {
    // Two different situations, and telling them apart matters: one is an
    // empty search, the other is results we cannot place. Saying "nothing to
    // show" for the second would suggest the search failed when it did not.
    final bool nothingFound = widget.listings.isEmpty;
    return Container(
      color: GoOutsColors.dividerGray,
      child: Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: <Widget>[
              const Icon(Icons.map_outlined,
                  size: 48, color: GoOutsColors.outlineVariant),
              const SizedBox(height: StaySpacing.page),
              Text(
                nothingFound
                    ? 'Nothing to show on the map'
                    : 'These places have no map location yet',
                textAlign: TextAlign.center,
                style: StayType.cardTitle.on(GoOutsColors.deepNavy),
              ),
              const SizedBox(height: StaySpacing.card),
              Text(
                nothingFound
                    ? 'Try widening your search, or switch back to the list.'
                    : 'Switch back to the list to see them all.',
                textAlign: TextAlign.center,
                style: StayType.body.on(GoOutsColors.bodyText),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _listToggle() => Positioned(
        top: StaySpacing.inline,
        left: 0,
        right: 0,
        child: Center(
          child: ElevatedButton.icon(
            onPressed:
                widget.onShowList ?? () => Navigator.of(context).maybePop(),
            icon: const Icon(Icons.format_list_bulleted, size: 18),
            label: Text('List', style: StayType.buttonText),
            style: ElevatedButton.styleFrom(
              backgroundColor: GoOutsColors.primaryBlue,
              foregroundColor: GoOutsColors.cardSurface,
              elevation: 4,
              padding: const EdgeInsets.symmetric(
                  horizontal: 28, vertical: StaySpacing.inline),
              shape: const StadiumBorder(),
            ),
          ),
        ),
      );

  Widget _carousel(List<StayListing> listings) => Positioned(
        bottom: StaySpacing.inline,
        left: 0,
        right: 0,
        height: 124,
        child: PageView.builder(
          controller: _cards,
          itemCount: listings.length,
          onPageChanged: (int i) {
            setState(() => _selected = i);
            _rebuildMarkers();
            final StayListing l = listings[i];
            _map?.animateCamera(
              CameraUpdate.newLatLng(LatLng(l.lat!, l.lng!)),
            );
          },
          itemBuilder: (BuildContext context, int i) => Padding(
            padding: const EdgeInsets.symmetric(horizontal: 6),
            child: _card(listings[i]),
          ),
        ),
      );

  Widget _card(StayListing l) {
    final StayPartnerCounts? partners = l.locationContext?.partnerCounts;
    return Material(
      color: GoOutsColors.cardSurface,
      borderRadius: BorderRadius.circular(12),
      clipBehavior: Clip.antiAlias,
      elevation: 4,
      shadowColor: Colors.black.withValues(alpha: 0.2),
      child: InkWell(
        onTap: () => _openListing(l.id),
        child: Row(
          children: <Widget>[
            SizedBox(
              width: 104,
              height: 124,
              child: l.coverPhotoUrl == null
                  ? Container(
                      color: GoOutsColors.dividerGray,
                      child: const Icon(Icons.home_outlined,
                          color: GoOutsColors.outlineVariant),
                    )
                  : Image.network(
                      l.coverPhotoUrl!,
                      fit: BoxFit.cover,
                      // Decode at display size. A full resolution decode per
                      // card is how a carousel eats memory.
                      cacheWidth: 220,
                      errorBuilder: (_, __, ___) => Container(
                        color: GoOutsColors.dividerGray,
                        child: const Icon(Icons.home_outlined,
                            color: GoOutsColors.outlineVariant),
                      ),
                    ),
            ),
            Expanded(
              child: Padding(
                padding: const EdgeInsets.all(StaySpacing.inline),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: <Widget>[
                    Text(
                      l.title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: StayType.cardTitle.on(GoOutsColors.deepNavy),
                    ),
                    const SizedBox(height: 2),
                    // Only when somebody has actually stayed. A bare "0.0" on
                    // a new listing reads as a bad property rather than a new
                    // one, and it is the host who pays for that.
                    if (l.ratingCount > 0)
                      Row(
                        children: <Widget>[
                          const Icon(Icons.star_rounded,
                              size: 15, color: GoOutsColors.warning),
                          const SizedBox(width: 3),
                          Text(l.ratingAvg.toStringAsFixed(1),
                              style: StayType.caption
                                  .on(GoOutsColors.deepNavy)
                                  .semibold),
                        ],
                      )
                    else
                      Text('New listing',
                          style: StayType.caption.on(GoOutsColors.bodyText)),
                    const SizedBox(height: 4),
                    Row(
                      crossAxisAlignment: CrossAxisAlignment.baseline,
                      textBaseline: TextBaseline.alphabetic,
                      children: <Widget>[
                        Text(l.nightlyRate.compact,
                            style: StayType.price.on(GoOutsColors.primaryBlue)),
                        const SizedBox(width: 4),
                        Text('nightly',
                            style:
                                StayType.priceUnit.on(GoOutsColors.bodyText)),
                      ],
                    ),
                    if (partners != null && partners.hasAny) ...<Widget>[
                      const SizedBox(height: 6),
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8, vertical: 3),
                        decoration: BoxDecoration(
                          color: GoOutsColors.paleBlueTint,
                          borderRadius: BorderRadius.circular(20),
                        ),
                        child: Text(
                          '${partners.halfMile} partners nearby',
                          style: StayType.caption.on(GoOutsColors.primaryBlue),
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}
